"use client";
import { useState, useEffect, useRef, useCallback } from "react";
import { Orbit as OrbitIcon, Home, FileText, Search, Plus, BookOpen, BriefcaseBusiness, Code2, Heart, Star, ChevronRight, ChevronDown, ListTodo, Trash2, LayoutGrid, List, Settings2, Download, Upload, Menu, X, Check, CheckCircle2, Circle, Clock3, MoreHorizontal, Bold, Italic, Heading2, ListChecks, Quote, Table2, PanelLeft, Eye, Columns2, Pencil, Copy, Undo2, Link2, ExternalLink, Loader2, FolderOpen, GripVertical, CalendarDays, Timer, Bell, Video, Network, Users, ChartNoAxesColumn, ArrowUpDown, SlidersHorizontal } from "lucide-react";
import { Button } from "@/components/ui/button";
import { EffectButton } from "@/components/ui/effect-button";
import { Dialog, DialogContent, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import Markdown from "react-markdown";
import remarkGfm from "remark-gfm";
import rehypeHighlight from "rehype-highlight";
import { areas, workspaceSchema, type Workspace, type Page, type Task } from "@/lib/workspace";
import { FocusTimerPanel } from "@/components/focus-timer";
import { TaskReminders } from "@/components/task-reminders";
import { VideoPreview } from "@/components/video-preview";
import { parseVideo } from "@/lib/video";
import { localDateTime, nextOccurrence, repeatLabels, scheduleLabel, recurrenceDay } from "@/lib/schedule";
import { DiagramPreview, MarkdownPre, DiagramEditContext } from "@/components/diagram-preview";
import { diagramTemplates, diagramFence, replaceDiagram, type DiagramTemplate, type DiagramRange } from "@/lib/diagrams";
import { PeoplePanel } from "@/components/people-panel";
import { ProgressPanel } from "@/components/progress-panel";
import { AgendaPanel } from "@/components/agenda-panel";
import { mergeWorkspace } from "@/lib/import-workspace";
const coverFor = (area:Page["area"])=>({Pessoal:"/design/personal.jpg",Estudos:"/design/study.jpg",Trabalho:"/design/home.jpg",Programação:"/design/code.jpg"})[area];
const areaInfo = {
 Pessoal:{icon:Heart,text:"Rotina, metas e o que importa.",class:"personal"},
 Estudos:{icon:BookOpen,text:"Conhecimento em construção.",class:"study"},
 Trabalho:{icon:BriefcaseBusiness,text:"Projetos que saem do papel.",class:"work"},
 Programação:{icon:Code2,text:"Código, documentação e ideias.",class:"code"},
};
const statuses:Task["status"][]=["A fazer","Em andamento","Concluído"];
type View="people"|"progress"|"more"|"agenda"|"timer"|"home"|"pages"|"tasks"|"favorites"|"trash"|"settings"|Page["area"];
function download(name:string,content:string,type="text/plain"){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function fileName(title:string){return title.replace(/[<>:"/\\|?*]/g,"-").trim()||"Sem título";}
function dateLabel(value:string){return value?new Date(value+"T12:00:00").toLocaleDateString("pt-BR",{day:"2-digit",month:"short"}):"Sem prazo";}
export default function Orbit(){
 const [workspace,setWorkspace]=useState<Workspace|null>(null);
 const [view,setView]=useState<View>("home");
 const [pageId,setPageId]=useState<string|null>(null);
 const [loading,setLoading]=useState(true);
 const [loadError,setLoadError]=useState("");
 const [error,setError]=useState("");
 const [status,setStatus]=useState<"saved"|"pending"|"saving"|"error">("saved");
 const [mobile,setMobile]=useState(false);
 const [searchOpen,setSearchOpen]=useState(false);
 const [query,setQuery]=useState("");
 const [newOpen,setNewOpen]=useState(false);
 const [newTitle,setNewTitle]=useState("");
 const [newArea,setNewArea]=useState<Page["area"]>("Pessoal");
 const [newParent,setNewParent]=useState<string|null>(null);
 const [taskOpen,setTaskOpen]=useState(false);
 const [taskDraft,setTaskDraft]=useState<Task|null>(null);
 const [board,setBoard]=useState(false);
 const [areaFilter,setAreaFilter]=useState("Todas");
 const [taskSort,setTaskSort]=useState(false);
 const [pageFilter,setPageFilter]=useState("");
 const [pageLayout,setPageLayout]=useState("list");
 const [editorMode,setEditorMode]=useState<"edit"|"split"|"preview">("preview");
 const [pageMenu,setPageMenu]=useState(false);
 const [slash,setSlash]=useState(false);
 const [language,setLanguage]=useState("typescript");
 const [toast,setToast]=useState("");
 const [diagramOpen,setDiagramOpen]=useState(false);
 const [diagramCode,setDiagramCode]=useState(diagramTemplates.flowchart.source);
 const [diagramTemplate,setDiagramTemplate]=useState<DiagramTemplate>("flowchart");
 const [diagramRange,setDiagramRange]=useState<DiagramRange|null>(null);
 const [diagramValid,setDiagramValid]=useState(false);
 const [diagramError,setDiagramError]=useState("");
 const startDiagram=()=>{setDiagramCode(diagramTemplates.flowchart.source);setDiagramTemplate("flowchart");setDiagramRange(null);setDiagramValid(false);setDiagramError("");setDiagramOpen(true);};
 const [videoOpen,setVideoOpen]=useState(false);
 const [videoUrl,setVideoUrl]=useState("");
 const [videoTitle,setVideoTitle]=useState("");
 const [videoError,setVideoError]=useState("");
 const [agendaDate,setAgendaDate]=useState("");
 const editor=useRef<HTMLTextAreaElement>(null);
 const importInput=useRef<HTMLInputElement>(null);
 const backupInput=useRef<HTMLInputElement>(null);
 const current=useRef<Workspace|null>(null);
 const revision=useRef(0);
 const lastSaved=useRef("");
 const saving=useRef(false);
 const conflict=useRef(false);
 const flushRef=useRef<()=>Promise<void>>(async()=>{});
 current.current=workspace;
 const load=useCallback(async()=>{setLoading(true);setLoadError("");try{const r=await fetch("/api/workspace",{cache:"no-store"});const data=await r.json() as {workspace:unknown;revision:number;error?:string};if(!r.ok)throw new Error(data.error);const valid=workspaceSchema.parse(data.workspace);lastSaved.current=JSON.stringify(valid);revision.current=data.revision;conflict.current=false;setWorkspace(valid);setError("");setStatus("saved");}catch(e){setLoadError(e instanceof Error?e.message:"Não foi possível abrir seu espaço.");}finally{setLoading(false);}},[]);
 useEffect(()=>{void load();},[load]);
 flushRef.current=async()=>{if(saving.current||!current.current||conflict.current)return;saving.current=true;try{while(current.current&&JSON.stringify(current.current)!==lastSaved.current){setStatus("saving");const snapshot=JSON.stringify(current.current);const r=await fetch("/api/workspace",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify({workspace:JSON.parse(snapshot),revision:revision.current})});const result=await r.json() as {revision:number;error?:string};if(!r.ok){if(r.status===409)conflict.current=true;throw new Error(result.error);}revision.current=result.revision;lastSaved.current=snapshot;}setStatus("saved");setError("");}catch(e){setStatus("error");setError(e instanceof Error?e.message:"Não foi possível salvar.");}finally{saving.current=false;}};
 useEffect(()=>{if(!workspace||JSON.stringify(workspace)===lastSaved.current)return;setStatus("pending");const timer=setTimeout(()=>void flushRef.current(),700);return()=>clearTimeout(timer);},[workspace]);
 useEffect(()=>{const handler=(event:BeforeUnloadEvent)=>{if(current.current&&JSON.stringify(current.current)!==lastSaved.current){event.preventDefault();event.returnValue="";}};window.addEventListener("beforeunload",handler);return()=>window.removeEventListener("beforeunload",handler);},[]);
 useEffect(()=>{const handler=(e:KeyboardEvent)=>{if((e.ctrlKey||e.metaKey)&&e.key==="k"){e.preventDefault();setSearchOpen(x=>!x);}if((e.ctrlKey||e.metaKey)&&e.key==="s"){e.preventDefault();void flushRef.current();}if(e.key==="Escape"){setMobile(false);setSlash(false);setPageMenu(false);}};window.addEventListener("keydown",handler);return()=>window.removeEventListener("keydown",handler);},[]);
 useEffect(()=>{if(toast){const t=setTimeout(()=>setToast(""),3000);return()=>clearTimeout(t);}},[toast]);
 const openPage=useCallback((id:string)=>{setPageId(id);setPageMenu(false);setMobile(false);setSearchOpen(false);setSlash(false);},[]);
 const navigate=(next:View)=>{setView(next);setPageId(null);setMobile(false);setPageMenu(false);setPageFilter("");};
 const updatePage=(id:string,change:Partial<Page>)=>setWorkspace(w=>w?{...w,pages:w.pages.map(p=>p.id===id?{...p,...change,updatedAt:new Date().toISOString()}:p)}:w);
 const patchTask=(id:string,change:Partial<Task>)=>setWorkspace(w=>w?{...w,tasks:w.tasks.map(t=>t.id===id?{...t,...change}:t)}:w);
 const finishTask=(task:Task)=>{if(task.status==="Concluído"){patchTask(task.id,{status:"A fazer"});return;}const next=nextOccurrence(task);patchTask(task.id,next?{status:"A fazer",scheduledAt:next,repeatDay:task.repeatDay??recurrenceDay(task)}:{status:"Concluído"});if(next)setToast("Tarefa concluída. Próxima ocorrência agendada.");};
 const enableNotifications=async()=>{if(!("Notification" in window)){setToast("Este navegador não oferece notificações. Os lembretes aparecem no Orbit.");return;}try{const permission=await Notification.requestPermission();setToast(permission==="granted"?"Notificações ativadas enquanto o Orbit estiver aberto.":"Os lembretes continuam aparecendo dentro do Orbit.");}catch{setToast("Os lembretes continuam aparecendo dentro do Orbit.");}};
 const createPage=(area:Page["area"]="Pessoal",parentId:string|null=null)=>{setNewTitle("");setNewArea(area);setNewParent(parentId);setNewOpen(true);};
 const submitPage=(e:React.FormEvent)=>{e.preventDefault();const id=crypto.randomUUID();const p:Page={id,title:newTitle.trim()||"Sem título",area:newArea,content:"",favorite:false,archived:false,parentId:newParent,updatedAt:new Date().toISOString()};setWorkspace(w=>w?{...w,pages:[...w.pages,p]}:w);setNewOpen(false);setEditorMode("edit");openPage(id);};
 const startTask=(task?:Task)=>{setTaskDraft(task||{id:crypto.randomUUID(),title:"",area:areas.includes(view as Page["area"])?view as Page["area"]:"Pessoal",status:"A fazer",priority:"Média",due:"",pageId:pageId});setTaskOpen(true);};
 const submitTask=(e:React.FormEvent)=>{e.preventDefault();if(!taskDraft?.title.trim())return;const form=new FormData(e.currentTarget as HTMLFormElement);const raw=String(form.get("schedule")??"");const date=raw?new Date(raw):null;if(date&&!Number.isFinite(date.getTime()))return;const draft={...taskDraft,due:String(form.get("due")??taskDraft.due),scheduledAt:date?.toISOString()??null,scheduleTimezone:raw===localDateTime(taskDraft.scheduledAt)?taskDraft.scheduleTimezone:Intl.DateTimeFormat().resolvedOptions().timeZone,repeatDay:raw===localDateTime(taskDraft.scheduledAt)?taskDraft.repeatDay:date?.getDate()};let valid={...draft,title:draft.title.trim(),repeat:draft.scheduledAt?draft.repeat??"none":"none",reminder:!!draft.scheduledAt&&!!draft.reminder,repeatDay:draft.scheduledAt?draft.repeatDay??recurrenceDay(draft):undefined};if(valid.status==="Concluído"&&workspace?.tasks.find(t=>t.id===valid.id)?.status!=="Concluído"){const next=nextOccurrence(valid);if(next)valid={...valid,status:"A fazer",scheduledAt:next};}setWorkspace(w=>w?{...w,tasks:w.tasks.some(t=>t.id===valid.id)?w.tasks.map(t=>t.id===valid.id?valid:t):[...w.tasks,valid]}:w);setTaskOpen(false);};
 const exportBackup=()=>{if(workspace)download("orbit-backup.json",JSON.stringify({version:1,exportedAt:new Date().toISOString(),workspace},null,2),"application/json");};
 const importMarkdown=async(file:File)=>{if(file.size>200000){setToast("O arquivo deve ter até 200 KB.");return;}const content=await file.text();const id=crypto.randomUUID();const p:Page={id,title:file.name.replace(/\.md$/i,""),area:areas.includes(view as Page["area"])?view as Page["area"]:"Pessoal",content,favorite:false,archived:false,parentId:null,updatedAt:new Date().toISOString()};setWorkspace(w=>w?{...w,pages:[...w.pages,p]}:w);openPage(id);setToast("Markdown importado.");};
 const importBackup=async(file:File)=>{try{if(file.size>4000000)throw new Error("Arquivo muito grande.");const parsed=JSON.parse(await file.text());const incoming=workspaceSchema.parse(parsed.workspace??parsed);const existing=current.current;if(!existing)return;const merged=workspaceSchema.parse(mergeWorkspace(existing,incoming));setWorkspace(merged);setToast("Backup importado. Seu conteúdo existente foi preservado.");}catch{setToast("Não foi possível importar esse backup. Confira o formato e os limites do espaço.");}};
 useEffect(()=>{const doc=document as Document&{modelContext?:{registerTool:(tool:unknown,options:{signal:AbortSignal})=>void|Promise<void>}};if(!doc.modelContext?.registerTool)return;const controller=new AbortController();const report=(e:unknown)=>{if(!controller.signal.aborted)console.error(e);};const register=(tool:unknown)=>{try{Promise.resolve(doc.modelContext!.registerTool(tool,{signal:controller.signal})).catch(report);}catch(e){report(e);}};
 register({name:"orbit_list_pages",description:"Lista as páginas do espaço aberto.",inputSchema:{type:"object",properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({pages:current.current?.pages.filter(p=>!p.archived).map(p=>({id:p.id,title:p.title,area:p.area}))??[]})});
 register({name:"orbit_open_page",description:"Abre uma página existente na interface, sem alterar seu conteúdo.",inputSchema:{type:"object",properties:{id:{type:"string"}},required:["id"],additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:unknown)=>{const id=(input as {id?:unknown})?.id;if(typeof id!=="string"||!current.current?.pages.some(p=>p.id===id&&!p.archived))throw new Error("Página não encontrada.");openPage(id);return {opened:id};}});
 return()=>controller.abort();},[openPage]);
 const pages=workspace?.pages.filter(p=>!p.archived)??[];
 const page=workspace?.pages.find(p=>p.id===pageId&&!p.archived);
 const tasks=workspace?.tasks??[];
 const completed=tasks.filter(t=>t.status==="Concluído").length;
 const pending=tasks.filter(t=>t.status!=="Concluído");
 const today=localDateTime(new Date().toISOString()).slice(0,10);
 const todayTasks=pending.filter(t=>{const date=t.scheduledAt?localDateTime(t.scheduledAt).slice(0,10):t.due;return !date||date<=today;});
 const scheduledTasks=pending.filter(t=>t.scheduledAt&&(!agendaDate||localDateTime(t.scheduledAt).slice(0,10)===agendaDate)).sort((a,b)=>a.scheduledAt!.localeCompare(b.scheduledAt!));
 const favorites=pages.filter(p=>p.favorite);
 const recent=[...pages].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).slice(0,4);
 const area=areas.includes(view as Page["area"])?view as Page["area"]:null;
 const filteredPages=(view==="trash"?workspace?.pages.filter(p=>p.archived)??[]:view==="favorites"?favorites:area?pages.filter(p=>p.area===area):pages).filter(p=>p.title.toLowerCase().includes(pageFilter.toLowerCase()));
 const filteredTasks=tasks.filter(t=>areaFilter==="Todas"||t.area===areaFilter).sort((a,b)=>taskSort?(a.scheduledAt||a.due||"9999").localeCompare(b.scheduledAt||b.due||"9999"):0);
 const searchResults=pages.filter(p=>(p.title+" "+p.content).toLocaleLowerCase().includes(query.toLocaleLowerCase()));
 const title=page?.title||(area??({agenda:"Agenda",timer:"Timer",home:"Início",people:"Pessoas",progress:"Meu progresso",more:"Seu espaço",pages:"Todas as páginas",tasks:"Tarefas",favorites:"Favoritos",trash:"Lixeira",settings:"Seu espaço"} as Record<string,string>)[view]);
 const insert=(before:string,after="",placeholder="")=>{if(!page)return;const el=editor.current;let start=el?.selectionStart??page.content.length;const end=el?.selectionEnd??start;if(slash&&page.content[start-1]==="/"){start-=1;}const selected=page.content.slice(start,end);const text=before+(selected||placeholder)+after;updatePage(page.id,{content:page.content.slice(0,start)+text+page.content.slice(end)});setSlash(false);requestAnimationFrame(()=>{if(!el)return;el.focus();el.setSelectionRange(start+before.length,start+before.length+(selected||placeholder).length);});};
 const pageTree=(items:Page[],parentId:string|null=null,depth=0):React.ReactNode=>items.filter(p=>p.parentId===parentId||(!parentId&&p.parentId&&!items.some(x=>x.id===p.parentId))).map(p=><div key={p.id}><button className={"nav-page "+(p.id===pageId?"active":"")} onClick={()=>openPage(p.id)} style={{paddingLeft:12+depth*12}}><FileText size={15}/><span>{p.title||"Sem título"}</span></button>{depth<6&&pageTree(items,p.id,depth+1)}</div>);
 const pageCard=(p:Page)=>{const Icon=areaInfo[p.area].icon;return <div className="page-card" key={p.id}><button className="page-open" onClick={()=>view==="trash"?undefined:openPage(p.id)} disabled={view==="trash"}>{pageLayout!=="list"&&<img className="page-card-cover" src={coverFor(p.area)} alt=""/>}<FileText size={16}/><h3>{p.title||"Sem título"}</h3><span className={"area-label "+areaInfo[p.area].class}>{p.area}</span><span className="card-date">{new Date(p.updatedAt).toLocaleDateString("pt-BR",{day:"numeric",month:"short",year:"numeric"})}</span></button>{view==="trash"?<Button variant="ghost" className="restore" onClick={()=>updatePage(p.id,{archived:false})}><Undo2 size={14}/>Restaurar</Button>:<button aria-label={p.favorite?"Remover dos favoritos":"Adicionar aos favoritos"} className={"card-star "+(p.favorite?"starred":"")} onClick={()=>updatePage(p.id,{favorite:!p.favorite})}><Star size={14}/></button>}</div>;};
 const taskRow=(t:Task)=>{return <div className={"task-row "+(t.status==="Concluído"?"done":"")} key={t.id}><button className="task-check" aria-label={t.status==="Concluído"?"Reabrir tarefa":"Concluir tarefa"} onClick={()=>finishTask(t)}>{t.status==="Concluído"?<Check size={13}/>:null}</button><button className="task-name" onClick={()=>startTask(t)}>{t.title}<span className="task-mobile-detail">{t.area} · {scheduleLabel(t)||dateLabel(t.due)}</span></button><span className={"task-status task-status-"+statuses.indexOf(t.status)}>{t.status}</span><span className={"task-area area-label "+areaInfo[t.area].class}>{t.area}</span><span className={"priority priority-"+t.priority.toLowerCase()}>{t.priority}</span><span className="task-due">{scheduleLabel(t)||dateLabel(t.due)}</span><button className="icon-button" aria-label="Editar tarefa" onClick={()=>startTask(t)}><MoreHorizontal size={17}/></button></div>;};
 return <div className="app-shell">
 <input ref={importInput} type="file" accept=".md,text/markdown" hidden onChange={e=>{const file=e.target.files?.[0];if(file)void importMarkdown(file);e.target.value="";}}/>
 <input ref={backupInput} type="file" accept=".json,application/json" hidden onChange={e=>{const file=e.target.files?.[0];if(file)void importBackup(file);e.target.value="";}}/>
 {mobile&&<button className="sidebar-shade" onClick={()=>setMobile(false)} aria-label="Fechar navegação"/>}
 <aside className={"sidebar "+(mobile?"mobile-open":"")}>
  <button className="brand" onClick={()=>navigate("home")}><OrbitIcon size={21} strokeWidth={1.6}/><span>Orbit</span><ChevronDown size={13}/></button>
  <button className="search-trigger" onClick={()=>setSearchOpen(true)}><Search size={16}/><span>Buscar</span><kbd>Ctrl K</kbd></button>
  <nav aria-label="Navegação principal">{([{id:"home",label:"Início",icon:Home},{id:"tasks",label:"Tarefas",icon:ListTodo},{id:"agenda",label:"Agenda",icon:CalendarDays},{id:"timer",label:"Timer",icon:Timer},{id:"pages",label:"Todas as páginas",icon:FileText},{id:"people",label:"Pessoas",icon:Users},{id:"progress",label:"Meu progresso",icon:ChartNoAxesColumn}] as const).map(item=><button key={item.id} className={"nav-item "+(view===item.id&&!page?"active":"")} onClick={()=>navigate(item.id)}><item.icon size={16}/><span>{item.label}</span></button>)}</nav>
  <div className="nav-section-label"><button onClick={()=>navigate("favorites")}>Favoritos</button></div>
  <div className="favorite-pages">{pageTree(favorites)}{!favorites.length&&<span className="nav-hint">Suas páginas favoritas ficam aqui.</span>}</div>
  <div className="nav-section-label">Espaços</div>
  <nav aria-label="Áreas">{areas.map(a=>{const Icon=areaInfo[a].icon;return <button key={a} className={"nav-item "+(view===a&&!page?"active":"")} onClick={()=>navigate(a)}><Icon size={16} className={"area-stroke "+areaInfo[a].class}/><span>{a}</span></button>;})}<button className="nav-item" onClick={()=>createPage()}><Plus size={16}/><span>Nova página</span></button></nav>
  <div className="sidebar-bottom"><button className="nav-item" onClick={()=>navigate("settings")}><Settings2 size={16}/><span>Configurações e Codex</span></button><button className="nav-item" onClick={()=>navigate("trash")}><Trash2 size={16}/><span>Lixeira</span></button><div className="account"><span className="avatar">O</span><strong>Meu espaço</strong><ChevronDown size={13}/></div></div>
 </aside>
 <div className="main-shell">
  <header className="topbar"><div className="breadcrumb"><button className="icon-button mobile-toggle" aria-label="Abrir navegação" onClick={()=>setMobile(true)}><Menu size={20}/></button><button className="breadcrumb-home" onClick={()=>navigate("home")}><Home size={14}/><span className="desktop-brand">Orbit</span><span className="mobile-brand"><OrbitIcon size={18}/>Orbit</span></button><span className="breadcrumb-slash">/</span><strong>{page? page.area+" / "+(title||"Sem título"):title}</strong></div><div className="topbar-actions"><span className={"save-status "+(status==="error"?"error":"")}>{status==="saved"?<Check size={13}/>:status==="error"?<Clock3 size={13}/>:<Loader2 size={13} className="spin"/>}{status==="saved"?"Salvo":status==="error"?"Não salvo":status==="saving"?"Salvando":"Alterações pendentes"}</span><button className="icon-button desktop-action" onClick={()=>void enableNotifications()} aria-label="Ativar notificações"><Bell size={15}/></button><button className="icon-button" onClick={()=>setSearchOpen(true)} aria-label="Buscar"><Search size={17}/></button></div></header>
  {error&&<div className="error-banner" role="alert"><span>{error}</span><Button variant="outline" size="sm" onClick={exportBackup}>Exportar rascunho</Button><Button variant="outline" size="sm" onClick={()=>conflict.current?void load():void flushRef.current()}>{conflict.current?"Recarregar":"Tentar salvar"}</Button></div>}
  {loading?<main className="main-content loading-workspace" aria-busy="true"><h1>Abrindo seu espaço…</h1><div className="loading-grid">{Array.from({length:6},(_,i)=><div key={i} className="loading-placeholder"><div/><span/><span/></div>)}</div></main>:loadError?<main className="loading-state"><FolderOpen size={34}/><h1>Não foi possível abrir seu espaço</h1><p>{loadError}</p><Button onClick={()=>void load()}>Tentar novamente</Button><a href="/login" target="_top">Entrar na minha conta</a></main>:<><div className={"orbit-cover "+(view==="home"&&!page?"home-cover":page?"editor-cover":"hidden")}><img src={page?coverFor(page.area):"/design/home.jpg"} alt=""/></div><main className={"main-content "+(page?"editor-main":view==="home"?"home-main":"")}>
  <div hidden={view!=="timer"||!!page}>
   <div className="page-heading"><div><div className="page-symbol"><Timer size={36}/></div><h1>Uma coisa por vez</h1><p className="subtitle">Escolha uma tarefa, reserve um tempo e encontre seu ritmo.</p></div></div>
   <FocusTimerPanel value={workspace?.timer} tasks={tasks} onFinish={session=>{setWorkspace(w=>w?{...w,focusSessions:[...w.focusSessions,{id:crypto.randomUUID(),date:new Date().toISOString(),...session}].slice(-5000)}:w);setToast("Timer concluído. Hora de fazer uma pausa.");}} onChange={timer=>setWorkspace(w=>w?{...w,timer}:w)}/>
  </div>
  {view==="agenda"&&!page&&<AgendaPanel tasks={tasks} onEditTask={startTask} onCreateTask={date=>{startTask();if(date)setTaskDraft(t=>t?{...t,due:date}:t)}} onFinishTask={finishTask} onEnableNotifications={()=>void enableNotifications()}/>}
  {view==="people"&&!page&&workspace&&<PeoplePanel workspace={workspace} onChange={updater=>setWorkspace(w=>w?updater(w):w)}/>}
  {view==="progress"&&!page&&workspace&&<ProgressPanel workspace={workspace} onChange={updater=>setWorkspace(w=>w?updater(w):w)} onEditTask={startTask}/>}
  {view==="more"&&!page&&<section className="mobile-more"><h1>Seu espaço</h1><p>Tudo o que faz parte da sua órbita.</p>{([{id:"people",label:"Pessoas",detail:"Contatos, encontros e memórias",icon:Users},{id:"progress",label:"Meu progresso",detail:"Metas e gráficos",icon:ChartNoAxesColumn},{id:"agenda",label:"Agenda",detail:"Sua semana em um lugar",icon:CalendarDays},{id:"timer",label:"Timer",detail:"Tempo para se concentrar",icon:Timer}] as const).map(x=><button key={x.id} onClick={()=>navigate(x.id)}><x.icon size={21}/><span><strong>{x.label}</strong><small>{x.detail}</small></span><ChevronRight size={16}/></button>)}<h2>Espaços</h2>{areas.map(a=>{const Icon=areaInfo[a].icon;return <button key={a} onClick={()=>navigate(a)}><Icon size={21} className={"area-stroke "+areaInfo[a].class}/>{a}<ChevronRight size={16}/></button>})}<button onClick={()=>navigate("settings")}><Settings2 size={21}/><span>Configurações e Codex</span><ChevronRight size={16}/></button><button onClick={()=>navigate("trash")}><Trash2 size={21}/>Lixeira<ChevronRight size={16}/></button></section>}
  {view==="home"&&!page&&<>
   <div className="welcome-row"><div><div className="page-symbol personal"><OrbitIcon size={30}/></div><h1>Meu espaço</h1><p className="subtitle">{new Date().toLocaleDateString("pt-BR",{weekday:"long",day:"numeric",month:"long"})}<span className="desktop-intro"> · Um lugar para suas notas, projetos e próximos passos.</span></p></div></div>
   <div className="home-shortcuts"><Button onClick={()=>createPage()}><Plus size={15}/>Nova página</Button><Button variant="outline" onClick={()=>startTask()}><Plus size={15}/>Nova tarefa</Button><button className="text-button" onClick={()=>navigate("timer")}><Timer size={15}/>Iniciar foco</button></div>
   <section className="home-recent"><div className="section-heading"><h2>Continue de onde parou</h2></div><div className="recent-grid">{recent.slice(0,3).map(p=><button className="recent-page" key={p.id} onClick={()=>openPage(p.id)}><img src={coverFor(p.area)} alt=""/><FileText className="recent-mobile-icon" size={17}/><div><strong>{p.title}</strong><span>{p.area}</span></div><ChevronRight className="recent-arrow" size={14}/></button>)}</div>{!recent.length&&<div className="empty-inline"><FileText size={21}/><div><strong>Seu espaço começa aqui</strong><p>Crie sua primeira página para guardar uma ideia.</p></div><Button onClick={()=>createPage()}>Nova página</Button></div>}</section>
   <div className="home-columns"><section className="tasks-section"><div className="section-heading"><h2>Hoje</h2><button className="text-button" onClick={()=>navigate("agenda")}>Ver agenda <ChevronRight size={13}/></button></div><div className="task-list compact">{todayTasks.slice(0,4).map(taskRow)}{!todayTasks.length&&<div className="empty-small">Tudo em dia. Um pouco de espaço para o próximo passo.</div>}<button className="add-inline" onClick={()=>startTask()}><Plus size={14}/>Adicionar tarefa</button></div></section><section className="home-spaces"><div className="section-heading"><h2>Seus espaços</h2></div><div className="space-grid">{areas.map(a=>{const Icon=areaInfo[a].icon;return <button className={"space-card "+areaInfo[a].class} key={a} onClick={()=>navigate(a)}><Icon size={16}/><strong>{a}</strong><span>{pages.filter(p=>p.area===a).length} páginas</span></button>;})}</div></section></div>
   <section className="quick-capture"><Pencil size={21}/><div><strong>Uma ideia para guardar?</strong><p>Escreva uma nota ou abra uma página em branco.</p></div><Button variant="outline" onClick={()=>createPage()}>Nova página</Button></section><footer className="home-footer">Orbit · Seu espaço, no seu ritmo.</footer>
  </>}
  {!page&&(view==="pages"||view==="favorites"||view==="trash"||area)&&<>
   <div className="page-heading"><div><div className="page-symbol"><FileText size={36}/></div><h1>{title}</h1><p className="subtitle">{area?areaInfo[area].text:view==="favorites"?"As páginas que você quer manter por perto.":view==="trash"?"Suas páginas ficam aqui até você restaurá-las.":"Notas, estudos e projetos. Tudo o que você quer encontrar."}</p></div>{view!=="trash"&&<EffectButton effect="shine" className="primary-action" onClick={()=>createPage(area??"Pessoal")}><Plus size={17}/>Nova página</EffectButton>}</div>
   <div className="collection-toolbar"><div className="tabs"><button className={view!=="favorites"?"selected":""} onClick={()=>navigate(area??"pages")}><Table2 size={15}/>Todas as páginas</button><button className={view==="favorites"?"selected":""} onClick={()=>navigate("favorites")}><Star size={15}/>Favoritos</button></div><div className="toolbar-right"><div className="inline-search"><Search size={15}/><input aria-label="Filtrar páginas" placeholder="Encontrar uma página…" value={pageFilter} onChange={e=>setPageFilter(e.target.value)}/></div><Button variant="ghost" onClick={()=>importInput.current?.click()}><Upload size={14}/>Importar .md</Button><div className="segmented"><button className={pageLayout==="grid"?"selected":""} onClick={()=>setPageLayout("grid")} aria-label="Exibir grade"><LayoutGrid size={15}/></button><button className={pageLayout==="list"?"selected":""} onClick={()=>setPageLayout("list")} aria-label="Exibir lista"><List size={15}/></button></div></div></div>
   {pageLayout==="list"&&!!filteredPages.length&&<div className="pages-table-heading"><span>Nome</span><span>Espaço</span><span>Última edição</span><span>Favorito</span></div>}<div className={"pages-grid "+(pageLayout==="list"?"pages-list":"")}>{filteredPages.map(pageCard)}</div>{!filteredPages.length&&<div className="empty-state"><FileText size={32}/><h2>{view==="trash"?"A lixeira está vazia":"Uma página em branco"}</h2><p>{pageFilter?"Nenhuma página encontrada.":"Crie uma página e encontre um espaço para suas ideias."}</p>{view!=="trash"&&<Button onClick={()=>createPage(area??"Pessoal")}>Criar página</Button>}</div>}<p className="collection-count">{filteredPages.length} páginas</p>
   {area&&<section className="area-tasks"><div className="section-heading"><h2>Tarefas de {area.toLowerCase()}</h2><button className="text-button" onClick={()=>startTask()}><Plus size={15}/>Adicionar tarefa</button></div><div className="task-list">{tasks.filter(t=>t.area===area).map(taskRow)}</div></section>}
  </>}
  {view==="tasks"&&!page&&<>
   <div className="page-heading"><div><div className="page-symbol"><ListTodo size={36}/></div><h1>Tarefas</h1><p className="subtitle">{completed} de {tasks.length} concluídas. Planeje o próximo passo e acompanhe o que está em andamento.</p></div><EffectButton effect="shine" className="primary-action" onClick={()=>startTask()}><Plus size={17}/>Nova tarefa</EffectButton></div>
   <div className="collection-toolbar"><div className="tabs"><button className={!board?"selected":""} onClick={()=>setBoard(false)}><Table2 size={15}/>Todas as tarefas</button><button className={board?"selected":""} onClick={()=>setBoard(true)}><Columns2 size={16}/>Quadro</button></div><select aria-label="Filtrar tarefas por área" value={areaFilter} onChange={e=>setAreaFilter(e.target.value)}><option value="Todas">Todos os espaços</option>{areas.map(a=><option key={a}>{a}</option>)}</select><button className="text-button" onClick={()=>setTaskSort(x=>!x)} aria-pressed={taskSort}><ArrowUpDown size={14}/>{taskSort?"Por data":"Ordenar"}</button></div>
   {board?<div className="kanban">{statuses.map(s=><section key={s} className="kanban-column" onDragOver={e=>e.preventDefault()} onDrop={e=>{e.preventDefault();const id=e.dataTransfer.getData("text/plain");const task=tasks.find(t=>t.id===id);if(task){if(s==="Concluído"&&task.status!=="Concluído")finishTask(task);else patchTask(id,{status:s});}}}><h2><span className={"status-dot status-"+statuses.indexOf(s)}/>{s}<span>{filteredTasks.filter(t=>t.status===s).length}</span></h2>{filteredTasks.filter(t=>t.status===s).map(t=><div className="kanban-task" draggable onDragStart={e=>e.dataTransfer.setData("text/plain",t.id)} key={t.id}><button onClick={()=>startTask(t)}><strong>{t.title}</strong><span>{t.area}</span></button><div className="kanban-meta"><span className={"priority priority-"+t.priority.toLowerCase()}>{t.priority}</span><span>{scheduleLabel(t)||dateLabel(t.due)}</span></div><select aria-label={"Status de "+t.title} value={t.status} onChange={e=>e.target.value==="Concluído"?finishTask(t):patchTask(t.id,{status:e.target.value as Task["status"]})}>{statuses.map(status=><option key={status}>{status}</option>)}</select></div>)}<button className="add-inline" onClick={()=>{startTask();setTaskDraft(d=>d?{...d,status:s}:d);}}><Plus size={15}/>Adicionar</button></section>)}</div>:<div className="task-list full-task-list"><div className="task-table-heading"><span>Tarefa</span><span>Status</span><span>Espaço</span><span>Prioridade</span><span>Prazo</span></div>{filteredTasks.map(taskRow)}<button className="add-inline" onClick={()=>startTask()}><Plus size={16}/>Adicionar tarefa</button></div>}
  </>}
  {page&&<>
   <div className="page-symbol editor-symbol"><Pencil size={34}/></div><div className="document-controls"><div><span className={"area-label "+areaInfo[page.area].class}>{page.area}</span><span className="document-meta">Atualizada em {new Date(page.updatedAt).toLocaleDateString("pt-BR")}</span></div><div className="document-actions"><button aria-label={page.favorite?"Remover dos favoritos":"Adicionar aos favoritos"} className={"icon-button "+(page.favorite?"starred":"")} onClick={()=>updatePage(page.id,{favorite:!page.favorite})}><Star size={18}/></button><button className="icon-button" aria-label="Exportar Markdown" onClick={()=>download(fileName(page.title)+".md",page.content)}><Download size={18}/></button><div className="menu-anchor"><button className="icon-button" aria-label="Opções da página" onClick={()=>setPageMenu(x=>!x)}><MoreHorizontal size={20}/></button>{pageMenu&&<div className="popup-menu"><button onClick={()=>{createPage(page.area,page.id);setPageMenu(false);}}><Plus size={16}/>Criar subpágina</button><button onClick={()=>{const id=crypto.randomUUID();setWorkspace(w=>w?{...w,pages:[...w.pages,{...page,id,title:page.title+" — cópia",updatedAt:new Date().toISOString()}]}:w);openPage(id);}}><Copy size={16}/>Duplicar página</button><button onClick={()=>{updatePage(page.id,{archived:true});setPageId(null);setPageMenu(false);setToast("Página movida para a lixeira.");}}><Trash2 size={16}/>Mover para a lixeira</button></div>}</div></div></div>
   <input className="document-title" aria-label="Título da página" value={page.title} maxLength={200} onChange={e=>updatePage(page.id,{title:e.target.value})} placeholder="Sem título"/>
   <div className="document-properties"><label>Espaço<select aria-label="Espaço da página" value={page.area} onChange={e=>updatePage(page.id,{area:e.target.value as Page["area"]})}>{areas.map(a=><option key={a}>{a}</option>)}</select></label><label>Página pai<select aria-label="Página pai" value={page.parentId??""} onChange={e=>updatePage(page.id,{parentId:e.target.value||null})}><option value="">Nenhuma</option>{pages.filter(p=>{if(p.id===page.id)return false;let current:Page|undefined=p;const visited=new Set<string>();while(current?.parentId){if(current.parentId===page.id||visited.has(current.id))return false;visited.add(current.id);current=pages.find(x=>x.id===current!.parentId);}return true;}).map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label></div>
   {pages.some(p=>p.parentId===page.id)&&<div className="subpages">{pages.filter(p=>p.parentId===page.id).map(p=><button key={p.id} onClick={()=>openPage(p.id)}><FileText size={15}/>{p.title}<ChevronRight size={14}/></button>)}</div>}
   <div className="editor-bar"><div className="format-actions"><button aria-label="Negrito" onClick={()=>insert("**","**","texto")}><Bold size={16}/></button><button aria-label="Itálico" onClick={()=>insert("*","*","texto")}><Italic size={16}/></button><span className="toolbar-divider"/><button aria-label="Título" onClick={()=>insert("\n## ","\n","Título")}><Heading2 size={18}/></button><button aria-label="Lista de tarefas" onClick={()=>insert("\n- [ ] ","\n","Uma tarefa")}><ListChecks size={18}/></button><button aria-label="Citação" onClick={()=>insert("\n> ","\n","Uma ideia")}><Quote size={16}/></button><button aria-label="Tabela" onClick={()=>insert("\n| Coluna 1 | Coluna 2 |\n| --- | --- |\n| | |\n")}><Table2 size={17}/></button><button aria-label="Inserir diagrama" title="Inserir diagrama" onClick={startDiagram}><Network size={18}/></button><button aria-label="Inserir vídeo" onClick={()=>{setVideoUrl("");setVideoTitle("");setVideoError("");setVideoOpen(true);}}><Video size={18}/></button><button aria-label="Inserir bloco de código" onClick={()=>insert("\n```"+language+"\n","\n```\n","// seu código")}><Code2 size={18}/></button><select aria-label="Linguagem de código" value={language} onChange={e=>setLanguage(e.target.value)}>{["typescript","javascript","python","html","css","json","bash","sql"].map(l=><option key={l}>{l}</option>)}</select></div><div className="segmented editor-tabs"><button title="Editar" aria-label="Modo escrever" className={editorMode==="edit"?"selected":""} onClick={()=>setEditorMode("edit")}><Pencil size={15}/><span>Editar</span></button><button title="Lado a lado" aria-label="Modo lado a lado" className={editorMode==="split"?"selected":""} onClick={()=>setEditorMode("split")}><Columns2 size={15}/><span>Markdown</span></button><button title="Visualizar" aria-label="Modo visualizar" className={editorMode==="preview"?"selected":""} onClick={()=>setEditorMode("preview")}><Eye size={16}/><span>Prévia</span></button></div></div>
   <div className={"editor-surface mode-"+editorMode}>{editorMode!=="preview"&&<div className="markdown-source"><div className="editor-pane-label">MARKDOWN<span>Ctrl S para salvar</span></div><textarea ref={editor} className="markdown-input" aria-label="Conteúdo Markdown" spellCheck={false} value={page.content} maxLength={200000} placeholder="Comece a escrever. Use / para inserir um bloco." onChange={e=>{updatePage(page.id,{content:e.target.value});const pos=e.target.selectionStart;setSlash(/(^|\n)\/$/.test(e.target.value.slice(0,pos)));}} onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==="b"){e.preventDefault();insert("**","**","texto");}if((e.ctrlKey||e.metaKey)&&e.key==="i"){e.preventDefault();insert("*","*","texto");}if(e.key==="Tab"){e.preventDefault();insert("  ");}}}/>{slash&&<div className="slash-menu"><span>INSERIR BLOCO</span>{[{label:"Título",icon:Heading2,action:()=>insert("## ","\n","Título")},{label:"Lista de tarefas",icon:ListChecks,action:()=>insert("- [ ] ","\n","Uma tarefa")},{label:"Diagrama",icon:Network,action:startDiagram},{label:"Código",icon:Code2,action:()=>insert("```"+language+"\n","\n```","// seu código")},{label:"Citação",icon:Quote,action:()=>insert("> ","\n","Uma ideia")}].map(x=><button key={x.label} onClick={x.action}><x.icon size={17}/>{x.label}</button>)}</div>}</div>}{editorMode!=="edit"&&<div className="markdown-preview"><div className="editor-pane-label">VISUALIZAÇÃO</div><div className="prose"><DiagramEditContext.Provider value={(source,start,end)=>{setDiagramCode(source);setDiagramRange({start,end,original:page.content.slice(start,end)});setDiagramValid(false);setDiagramError("");setDiagramOpen(true);}}><Markdown remarkPlugins={[remarkGfm]} rehypePlugins={[rehypeHighlight]} components={{pre:MarkdownPre,p:({children,node,...props})=>{const first=node?.children?.[0];if(node?.children?.length===1&&first?.type==="element"&&first.tagName==="a"){const video=parseVideo(String(first.properties?.href??""));if(video){const label=first.children?.filter(x=>x.type==="text").map(x=>x.value).join("");return <VideoPreview key={video.embed} video={video} title={label?.startsWith("https://")?undefined:label}/>;}}return <p {...props}>{children}</p>;},a:({children,...props})=><a {...props} target="_blank" rel="noopener noreferrer">{children}</a>}}>{page.content||"*Suas ideias ganham forma aqui.*"}</Markdown></DiagramEditContext.Provider></div></div>}</div>
   <div className="editor-footer"><span>{page.content.trim()?page.content.trim().split(/\s+/).length:0} palavras · {page.content.length} caracteres</span><button onClick={()=>{void navigator.clipboard.writeText(page.content).then(()=>setToast("Markdown copiado.")).catch(()=>setToast("Use Exportar Markdown para salvar o arquivo."));}}><Copy size={13}/>Copiar Markdown</button></div>
  </>}
  {view==="settings"&&!page&&<>
   <div className="page-heading"><div><div className="eyebrow">DO SEU JEITO</div><h1>Seu espaço</h1><p className="subtitle">Seu conteúdo, suas ferramentas, seu próximo passo.</p></div></div>
   <section className="settings-card"><span className="settings-symbol"><Code2 size={23}/></span><div><h2>Orbit + Codex</h2><p>Conecte seu assistente ao MCP desta instalação para consultar páginas, salvar Markdown e organizar tarefas.</p><p>O endpoint é <strong>/mcp</strong>. Gere seu token com <strong>npm run token</strong>.</p><a className="outline-link" href="https://github.com/SENPedroVitor/Orbit#conectar-ao-codex" target="_blank" rel="noopener noreferrer"><ExternalLink size={15}/>Como conectar</a></div></section>
   <section className="settings-card"><span className="settings-symbol"><Download size={23}/></span><div><h2>Seu conteúdo fica com você</h2><p>Exporte seu espaço completo como JSON ou importe páginas em Markdown. Ao importar um backup, as páginas são adicionadas sem apagar as existentes.</p><div className="settings-actions"><Button variant="outline" onClick={exportBackup}><Download size={16}/>Exportar backup</Button><Button variant="outline" onClick={()=>backupInput.current?.click()}><Upload size={16}/>Importar backup</Button><Button variant="outline" onClick={()=>importInput.current?.click()}><FileText size={16}/>Importar .md</Button></div></div></section>
   <section className="settings-card"><span className="settings-symbol"><Heart size={23}/></span><div><h2>Um espaço só seu</h2><p>As páginas e tarefas ficam no banco SQLite desta instalação. O acesso exige sua senha.</p><Button variant="ghost" onClick={async()=>{await fetch("/api/auth/logout",{method:"POST"});window.location.assign("/login");}}>Sair</Button><div className="workspace-stats"><span><strong>{pages.length}</strong> páginas</span><span><strong>{tasks.length}</strong> tarefas</span><span><strong>{favorites.length}</strong> favoritos</span></div></div></section>
  </>}
  </main></>}
 </div>
 <nav className="mobile-bottom-nav" aria-label="Navegação mobile">{([{id:"home",label:"Início",icon:Home},{id:"tasks",label:"Tarefas",icon:ListTodo},{id:"pages",label:"Páginas",icon:FileText},{id:"more",label:"Mais",icon:MoreHorizontal}] as const).map(x=><button key={x.id} className={(x.id==="pages"&&page)||(!page&&(view===x.id||(x.id==="more"&&["people","progress","agenda","timer","settings","trash",...areas].includes(view))))?"selected":""} onClick={()=>navigate(x.id)}><x.icon size={20}/><span>{x.label}</span></button>)}</nav>
 <Dialog open={searchOpen} onOpenChange={setSearchOpen}><DialogContent className="orbit-dialog search-dialog"><DialogTitle>Buscar no espaço</DialogTitle><DialogDescription>Encontre páginas pelo título ou conteúdo.</DialogDescription><div className="dialog-search"><Search size={19}/><input autoFocus aria-label="Buscar páginas" placeholder="O que você está procurando?" value={query} onChange={e=>setQuery(e.target.value)}/><kbd>ESC</kbd></div><div className="search-results">{searchResults.slice(0,15).map(p=><button key={p.id} onClick={()=>openPage(p.id)}><FileText size={18}/><span><strong>{p.title}</strong><small>{p.area}</small></span><ChevronRight size={14}/></button>)}{!searchResults.length&&<p>Nenhuma página encontrada.</p>}</div></DialogContent></Dialog>
 <Dialog open={newOpen} onOpenChange={setNewOpen}><DialogContent className="orbit-dialog"><DialogTitle>Uma nova página</DialogTitle><DialogDescription>Dê um nome à sua próxima ideia.</DialogDescription><form onSubmit={submitPage} className="dialog-form"><label>Título<input autoFocus placeholder="Como vai se chamar?" aria-label="Nome da nova página" value={newTitle} onChange={e=>setNewTitle(e.target.value)} maxLength={200}/></label><label>Espaço<select value={newArea} onChange={e=>setNewArea(e.target.value as Page["area"])}>{areas.map(a=><option key={a}>{a}</option>)}</select></label>{newParent&&<p className="form-note">Subpágina de {pages.find(p=>p.id===newParent)?.title}</p>}<div className="dialog-footer"><Button type="button" variant="ghost" onClick={()=>setNewOpen(false)}>Cancelar</Button><Button type="submit"><Plus size={16}/>Criar página</Button></div></form></DialogContent></Dialog>
 <Dialog open={taskOpen} onOpenChange={setTaskOpen}><DialogContent className="orbit-dialog"><DialogTitle>{tasks.some(t=>t.id===taskDraft?.id)?"Editar tarefa":"Nova tarefa"}</DialogTitle><DialogDescription>Organize o que quer fazer.</DialogDescription>{taskDraft&&<form className="dialog-form" onSubmit={submitTask}><label>Tarefa<input autoFocus required maxLength={300} aria-label="Nome da tarefa" placeholder="O que precisa ser feito?" value={taskDraft.title} onChange={e=>setTaskDraft({...taskDraft,title:e.target.value})}/></label><div className="form-grid"><label>Espaço<select value={taskDraft.area} onChange={e=>setTaskDraft({...taskDraft,area:e.target.value as Task["area"]})}>{areas.map(a=><option key={a}>{a}</option>)}</select></label><label>Status<select value={taskDraft.status} onChange={e=>setTaskDraft({...taskDraft,status:e.target.value as Task["status"]})}>{statuses.map(s=><option key={s}>{s}</option>)}</select></label><label>Prioridade<select value={taskDraft.priority} onChange={e=>setTaskDraft({...taskDraft,priority:e.target.value as Task["priority"]})}>{["Baixa","Média","Alta"].map(s=><option key={s}>{s}</option>)}</select></label><label>Prazo<input aria-label="Prazo da tarefa" name="due" type="date" value={taskDraft.due} onChange={e=>setTaskDraft({...taskDraft,due:e.target.value})}/></label></div><div className="schedule-fields"><h3><CalendarDays size={17}/>Agendamento</h3><label>Data e horário<input aria-label="Data e horário da tarefa" type="datetime-local" name="schedule" defaultValue={localDateTime(taskDraft.scheduledAt)}/></label><label>Repetição<select aria-label="Repetição da tarefa"  value={taskDraft.repeat??"none"} onChange={e=>setTaskDraft({...taskDraft,repeat:e.target.value as Task["repeat"]})}>{Object.entries(repeatLabels).map(([value,label])=><option key={value} value={value}>{label}</option>)}</select></label><label className="checkbox-label"><input type="checkbox"  checked={!!taskDraft.reminder} onChange={e=>setTaskDraft({...taskDraft,reminder:e.target.checked})}/>Lembrar com o Orbit aberto</label></div><label>Página relacionada<select value={taskDraft.pageId??""} onChange={e=>setTaskDraft({...taskDraft,pageId:e.target.value||null})}><option value="">Nenhuma</option>{pages.map(p=><option key={p.id} value={p.id}>{p.title}</option>)}</select></label><label>Notas<textarea aria-label="Notas da tarefa" value={taskDraft.notes??""} maxLength={5000} onChange={e=>setTaskDraft({...taskDraft,notes:e.target.value})}/></label><div className="dialog-footer"><Button variant="ghost" type="button" onClick={()=>setTaskOpen(false)}>Cancelar</Button><Button type="submit">{tasks.some(t=>t.id===taskDraft?.id)?"Salvar alterações":"Criar tarefa"}</Button></div></form>}</DialogContent></Dialog>
 <Dialog open={diagramOpen} onOpenChange={setDiagramOpen}><DialogContent className="orbit-dialog diagram-dialog">
  <header className="diagram-dialog-header"><div className="diagram-dialog-icon"><Network size={20}/></div><div><DialogTitle>{diagramRange?"Editar diagrama":"Novo diagrama"}</DialogTitle><DialogDescription>Organize suas ideias e veja as conexões.</DialogDescription></div></header>
  <form onSubmit={e=>{e.preventDefault();if(!page||!diagramValid)return;try{if(diagramRange)updatePage(page.id,{content:replaceDiagram(page.content,diagramRange,diagramCode)});else insert("\n"+diagramFence(diagramCode)+"\n");setDiagramOpen(false);setToast("Diagrama salvo na página.");}catch(error){setDiagramError(error instanceof Error?error.message:"Não foi possível salvar o diagrama.");}}} className="diagram-form">
   <div className="diagram-builder">
    <div className="diagram-code-panel">
     {!diagramRange&&<div className="diagram-models" role="group" aria-label="Modelo de diagrama">{Object.entries(diagramTemplates).map(([id,template])=><button type="button" key={id} aria-pressed={diagramTemplate===id} onClick={()=>{const type=id as DiagramTemplate;setDiagramTemplate(type);setDiagramCode(diagramTemplates[type].source);setDiagramValid(false);}}>{template.label}</button>)}</div>}
     <label className="diagram-source"><span><Code2 size={15}/>Código<span className="diagram-language">Mermaid</span></span><textarea aria-label="Código do diagrama" value={diagramCode} maxLength={20000} spellCheck={false} onChange={e=>{setDiagramCode(e.target.value);setDiagramValid(false);setDiagramError("");}}/></label>
     <p className="diagram-code-hint">A prévia acompanha suas alterações.</p>
    </div>
    <DiagramPreview compact source={diagramCode} onReady={setDiagramValid}/>
   </div>
   {diagramError&&<p className="diagram-form-error" role="alert">{diagramError}</p>}
   <footer className="diagram-dialog-footer"><span><FileText size={14}/>Salvo nesta página</span><div><Button type="button" variant="ghost" onClick={()=>setDiagramOpen(false)}>Cancelar</Button><Button type="submit" disabled={!diagramValid}>Salvar diagrama</Button></div></footer>
  </form>
 </DialogContent></Dialog>
 <Dialog open={videoOpen} onOpenChange={setVideoOpen}><DialogContent className="orbit-dialog"><DialogTitle>Inserir vídeo</DialogTitle><DialogDescription>Cole um link de YouTube ou Vimeo para criar uma prévia.</DialogDescription><form className="dialog-form" onSubmit={e=>{e.preventDefault();if(!parseVideo(videoUrl.trim())){setVideoError("Use um link HTTPS de um vídeo do YouTube ou Vimeo.");return;}const label=(videoTitle.trim()||"Vídeo").replace(/[\[\]\n]/g,"");insert("\n["+label+"]("+videoUrl.trim().replace(/\(/g,"%28").replace(/\)/g,"%29")+")\n");setVideoOpen(false);}}><label>Link do vídeo<input required autoFocus type="url" aria-label="Link do vídeo" value={videoUrl} onChange={e=>{setVideoUrl(e.target.value);setVideoError("");}}/></label><label>Título opcional<input maxLength={200} aria-label="Título do vídeo" value={videoTitle} onChange={e=>setVideoTitle(e.target.value)}/></label>{videoError&&<p role="alert">{videoError}</p>}<div className="dialog-footer"><Button type="button" variant="ghost" onClick={()=>setVideoOpen(false)}>Cancelar</Button><Button type="submit"><Video size={16}/>Inserir vídeo</Button></div></form></DialogContent></Dialog>
 {workspace&&<TaskReminders tasks={tasks} onOpen={startTask}/>}
 {toast&&<div className="toast" role="status"><Check size={16}/>{toast}</div>}
 </div>;
}
